<template><main class="admin-content"><NuxtLink to="/admin/accounting" class="text-sm font-bold text-blue-600">← Accounting</NuxtLink><div class="mt-2 flex flex-wrap justify-between gap-3"><div><h1 class="text-3xl font-black">Sales & Invoices</h1><p class="text-slate-500">Paid shop orders automatically become accounting invoices and ledger entries.</p></div><button class="btn-secondary" @click="load">Refresh</button></div><div v-if="msg" class="my-4 rounded-lg bg-slate-100 p-3">{{msg}}</div><section v-if="unposted.length" class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Historical / Unposted Orders</h2><p class="mt-1 text-sm text-amber-700"><b>Not posted automatically.</b> This prevents historical sales being double-counted. Post only orders you want included in Kialla Accounting.</p><div class="mt-3 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Order</th><th>Date</th><th>Customer</th><th class="text-right">Total</th><th></th></tr></thead><tbody><tr v-for="o in unposted" :key="o.id" class="border-b"><td class="p-2 font-bold">#{{o.id}}</td><td>{{date(o.created_at)}}</td><td>{{o.customer_name||o.customer_email}}</td><td class="text-right">{{money(o.total)}}</td><td class="text-right"><button class="btn-primary" @click="postOrder(o)">Post</button></td></tr></tbody></table></div></section><section class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Accounting Invoices</h2><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Invoice</th><th>Date</th><th>Customer</th><th>Status</th><th class="text-right">GST</th><th class="text-right">Total</th><th>Journal</th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id" class="border-b"><td class="p-2 font-bold">{{i.invoice_number}}</td><td>{{i.invoice_date}}</td><td>{{i.customer_name||i.customer_email||'—'}}</td><td class="uppercase text-xs font-bold">{{i.status}}</td><td class="text-right">{{money(i.gst_amount)}}</td><td class="text-right font-bold">{{money(i.total)}}</td><td>#{{i.journal_id}}</td></tr><tr v-if="!invoices.length"><td colspan="7" class="p-8 text-center text-slate-500">No accounting invoices yet.</td></tr></tbody></table></div></section></main></template><script setup lang="ts">definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch}=useAdminFetch(),invoices=ref<any[]>([]),unposted=ref<any[]>([]),msg=ref("");const money=(v:any)=>new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD"}).format(Number(v||0)),date=(v:any)=>new Date(v).toLocaleDateString("en-AU");async function load(){[invoices.value,unposted.value]=await Promise.all([adminFetch("/api/admin/accounting/invoices"),adminFetch("/api/admin/accounting/unposted-orders")])}async function postOrder(o:any){if(!confirm(`Post Order #${o.id} to accounting? This creates a permanent invoice and journal.`))return;try{const x:any=await adminFetch("/api/admin/accounting/post-order",{method:"POST",body:{order_id:o.id}});msg.value=`${x.invoice_number||"Invoice"} posted.`;await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script><style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.btn-primary{@apply rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}</style>